import{_ as i,o as l,c as e,a2 as o}from"./chunks/framework.0o43zZ6z.js";const u=JSON.parse('{"title":"使用說明","description":"章節搜尋、離線閱讀與加入主畫面的操作說明。","frontmatter":{"title":"使用說明","description":"章節搜尋、離線閱讀與加入主畫面的操作說明。","outline":[2,3]},"headers":[],"relativePath":"guide.md","filePath":"guide.md"}'),r={name:"guide.md"};function t(n,a,s,d,h,p){return l(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="使用說明" tabindex="-1">使用說明 <a class="header-anchor" href="#使用說明" aria-label="Permalink to &quot;使用說明&quot;">​</a></h1><p>這是 Miller’s Anesthesia 第 10 版的繁體中文閱讀介面。87 章皆有繁中章名與主題索引，依九個臨床主題分組，並保留英文原文與原書章號。</p><h2 id="快速搜尋" tabindex="-1">快速搜尋 <a class="header-anchor" href="#快速搜尋" aria-label="Permalink to &quot;快速搜尋&quot;">​</a></h2><p>點選頂端「搜尋中文主題或英文關鍵字…」，輸入繁體中文醫學名詞、藥物名稱或章節內的關鍵字。電腦也可使用 <strong>⌘ K</strong> 或 <strong>Ctrl K</strong>。</p><ul><li>搜尋範圍包含已匯入章節的標題與內文；不包含待匯入的章節。</li><li>中文不需空格，例如「呼吸道管理」；英文字母不分大小寫，例如「propofol」。</li><li>中文連續雙字可以找到較長句子中的詞彙。建議使用兩個字以上的關鍵字；單一中文字只會匹配獨立的單字詞。</li><li>中文可搜尋章名與人工整理的主題索引，例如「氣道管理」「心臟麻醉」「神經阻斷」或「丙泊酚」。英文可搜尋全文，例如「propofol」。未收錄的中文同義詞不會自動翻譯為英文。</li><li>多個詞以空格分隔時，結果需同時符合各個詞。</li><li>搜尋結果提供相關段落，開啟後可透過「章節導覽」切換段落。</li><li>搜尋不會換算劑量、推論適應症或自動產生醫療建議；請閱讀原段落中的條件與單位。</li></ul><h2 id="章節閱讀" tabindex="-1">章節閱讀 <a class="header-anchor" href="#章節閱讀" aria-label="Permalink to &quot;章節閱讀&quot;">​</a></h2><p>有繁中臨床摘要的章節會在目錄標示「含臨床摘要」，內容依核心觀念、臨床處置、併發症與考點排列。點選摘要中的「原文第 N 頁」可跳到下方英文原文；頁碼為該章 PDF 頁序。摘要經自動來源檢查，仍需核對原文與現行臨床規範。尚無摘要的章節顯示英文原文。</p><p>每章摘要分成四個部分：核心觀念精要、臨床指引與處置決策、重要併發症與危機處理，以及臨床重點與考點。臨床處置再分為術前評估、術中監測與用藥、逐步介入；原文沒有提供的項目會明確標示，不另補寫。藥物保留英文學名，適用時附台灣慣用中文名稱。</p><p>首頁會顯示實際可讀取的繁中摘要數。在章節目錄勾選「只顯示有繁中摘要的章節」，可快速篩出摘要。這些摘要由 Gemini 整理並經自動引文、數值與語意檢查，尚未經臨床專家審閱。</p><p>在「章節目錄」可依章號、中文或英文標題、主題關鍵字篩選。九大分類涵蓋基礎醫學、藥理、監測、麻醉技術、疼痛、專科、小兒、重症與研究；章號沿用原書。「上一章」「下一章」依原書章號排列。</p><p>閱讀時，桌面右側顯示「本頁大綱」；手機右下方有「章節導覽」，段落名稱保留原文。向下捲動後會出現「快速回到頂部」。寬表格可左右滑動；程式碼會自動折行。</p><p>點選導覽列的外觀切換鈕，可在淺色與深色模式之間切換。手機的外觀切換位於右上角選單內。</p><h2 id="離線閱讀" tabindex="-1">離線閱讀 <a class="header-anchor" href="#離線閱讀" aria-label="Permalink to &quot;離線閱讀&quot;">​</a></h2><ol><li>首次使用請保持網路連線，開啟正式版網站。完整離線內容包含全文、圖表與原頁影像，建議先使用 Wi-Fi，並預留約 500 MiB 的裝置空間。</li><li>等待左下角顯示 <strong>「已可離線閱讀」</strong>。大型章節或圖檔可能需要較久時間。</li><li>完成後，所有已匯入章節、搜尋索引與本地附件皆可離線讀取，不必逐章開啟。</li><li>關閉網路後，狀態會變為「離線閱讀中」。可開啟尚未讀過的章節並搜尋。</li></ol><p>只有安裝圖示不代表快取已完成。瀏覽器可能因儲存空間不足、手動清除網站資料或長期未使用而移除快取；重新連線並確認狀態後即可再次離線使用。站外連結不包含在離線內容中。</p><div class="tip custom-block"><p class="custom-block-title">有新版本時</p><p>網站會提示「手冊有新版本」。選擇「立即更新」會重新載入頁面，套用新的章節與搜尋內容；也可以稍後再更新。</p></div><h2 id="安裝到主畫面" tabindex="-1">安裝到主畫面 <a class="header-anchor" href="#安裝到主畫面" aria-label="Permalink to &quot;安裝到主畫面&quot;">​</a></h2><h3 id="iphone-與-ipad-safari" tabindex="-1">iPhone 與 iPad：Safari <a class="header-anchor" href="#iphone-與-ipad-safari" aria-label="Permalink to &quot;iPhone 與 iPad：Safari&quot;">​</a></h3><ol><li>使用 <strong>Safari</strong> 開啟網站的 <strong>HTTPS 網址</strong>。</li><li>等待「已可離線閱讀」。</li><li>點選 Safari 的「分享」按鈕；部分版本需先開啟「⋯」選單。</li><li>選擇「加入主畫面」。若沒有顯示，可在分享選單中向下尋找或編輯動作。</li><li>確認名稱「米勒麻醉學」，若有「以網頁 App 開啟」選項請啟用，再點選「加入」。</li><li>從主畫面的圖示開啟一次，確認離線狀態；關閉網路後重新開啟並切換章節。</li></ol><p>Safari 不支援網站直接跳出 Android 式安裝視窗，請使用分享選單。</p><h3 id="android-chrome" tabindex="-1">Android：Chrome <a class="header-anchor" href="#android-chrome" aria-label="Permalink to &quot;Android：Chrome&quot;">​</a></h3><ol><li>使用 <strong>Chrome</strong> 開啟網站的 <strong>HTTPS 網址</strong>。</li><li>等待「已可離線閱讀」。</li><li>若網站出現「安裝手冊」，點選並確認；也可從 Chrome「⋮」選單選擇「安裝應用程式」或「加到主畫面」。文字會依版本而異。</li><li>從主畫面開啟，確認以獨立視窗顯示。</li><li>關閉網路，重新開啟一個未讀過的章節並搜尋。</li></ol><h2 id="內容與版本" tabindex="-1">內容與版本 <a class="header-anchor" href="#內容與版本" aria-label="Permalink to &quot;內容與版本&quot;">​</a></h2><p>內文由使用者提供的 PDF 轉為 Markdown，保留來源英文。繁中章名、主題索引及臨床分類為本網站整理，並非出版社正式中譯或原書分部名稱。版面擷取可能產生表格或公式誤差，請對照附帶的原頁影像或原始 PDF 核對。這是獨立閱讀介面，非出版社官方產品。</p><p>臨床使用前，請核對原文、劑量單位、適用族群與院內最新規範。</p><h2 id="閱讀記憶與畫重點" tabindex="-1">閱讀記憶與畫重點 <a class="header-anchor" href="#閱讀記憶與畫重點" aria-label="Permalink to &quot;閱讀記憶與畫重點&quot;">​</a></h2><p>章節上方的「標記已閱讀」可記住閱讀狀態，再按一次可取消。章節目錄會顯示已閱讀章數，並可篩選未閱讀章節。</p><p>選取章節內文後，按浮動列的「儲存重點」，即可加入黃色重點。「我的重點」可查看或逐筆刪除；摘要與展開後的英文原文皆可標記。若網站更新使原文位置無法確認，該筆重點會保留於清單，不會套用到其他文字。</p><p>紀錄僅保存在目前裝置的瀏覽器，離線時也能使用；不會跨裝置同步。清除網站資料或使用無痕模式可能使紀錄消失。</p>',29)])])}const m=i(r,[["render",t]]);export{u as __pageData,m as default};
